1	/*
2	 * OpenTelemetry init must run before anything that touches HTTP / ioredis /
3	 * undici, so the auto-instrumentations can patch them at import time. See
4	 * src/instrument.ts.
5	 */
6	import "./instrument";
7	
8	import { assertBootInvariants, BootInvariantError } from "./boot/invariants";
9	import { createApp } from "./config/app";
10	import { env } from "./config/env";
11	import {
12	  abortBootstrap,
13	  initializeErrorHandlers,
14	} from "./config/error-handlers";
15	import { logStartup } from "./config/logger";
16	import { initializeSentry } from "./config/sentry";
17	import { setupNotifications, setupQueues } from "./config/setup";
18	
19	// Initialize Sentry after OTel so error events pick up the OTel trace context.
20	initializeSentry();
21	
22	/*
23	 * Boot invariants gate everything else. A misconfigured deploy aborts
24	 * here with a structured error instead of surfacing as a 500 to the
25	 * first user who hits the affected code path.
26	 */
27	try {
28	  assertBootInvariants(env);
29	} catch (error) {
30	  if (error instanceof BootInvariantError) {
31	    abortBootstrap(error.message, "boot.invariants_failed", error);
32	  }
33	
34	  throw error;
35	}
36	
37	/*
38	 * Notifications boot is unconditional — channels + events power the inline
39	 * dispatch path even when QUEUES_ENABLED is false.
40	 */
41	setupNotifications();
42	
43	/*
44	 * Queues MUST finish initializing before the HTTP listener accepts
45	 * connections. Otherwise a request landing during the gap sees
46	 * QUEUES_ENABLED=true but a null QueueManager, falls through to inline
47	 * email send, and the operator gets unexplained latency spikes during
48	 * deploys. Boot order: env invariants → notifications + queues →
49	 * listen. setupQueues is allowed to throw — failure aborts the boot
50	 * via `abortBootstrap`, the listener never opens.
51	 */
52	if (env.QUEUES_ENABLED) {
53	  try {
54	    await setupQueues();
55	  } catch (error: unknown) {
56	    abortBootstrap(
57	      "Failed to initialize queues at boot",
58	      "queues.init_failed",
59	      error
60	    );
61	  }
62	}
63	
64	const app = createApp().listen(env.PORT);
65	
66	initializeErrorHandlers(app);
67	
68	logStartup(app.server?.hostname ?? "localhost", app.server?.port ?? env.PORT);
