1	import { StrictMode } from "react";
2	
3	import * as Sentry from "@sentry/react";
4	import { createRoot } from "react-dom/client";
5	
6	import { env } from "@/lib/env";
7	import { getErrorMessage } from "@/lib/errors/getErrorMessage";
8	import { logger } from "@/lib/logger/logger";
9	
10	import "@/assets/css/tailwind.css";
11	
12	import { App } from "./App";
13	
14	if (env.VITE_SENTRY_DSN !== "") {
15	  Sentry.init({
16	    dsn: env.VITE_SENTRY_DSN,
17	    environment: env.MODE,
18	    /*
19	     * 0 keeps Sentry error-capture-only on the browser side. `browserTracingIntegration`
20	     * stays loaded because it's what writes the W3C `traceparent` header on
21	     * outbound `/api/*` fetches — the API's OpenTelemetry SDK reads that
22	     * header to continue the trace server-side and ship spans to Tempo. With
23	     * rate 0 the browser doesn't send transactions to GlitchTip but still
24	     * generates trace ids, so a browser-raised error event still carries
25	     * `trace_id` for the GlitchTip → Tempo pivot.
26	     */
27	    tracesSampleRate: 0,
28	    replaysSessionSampleRate: 0,
29	    replaysOnErrorSampleRate: 1.0,
30	    integrations: [Sentry.browserTracingIntegration()],
31	    /*
32	     * Propagate `sentry-trace` + `traceparent` headers only on same-origin
33	     * API calls. Defaulting to "all origins" would leak the trace id to
34	     * CDNs and third-party services.
35	     */
36	    tracePropagationTargets: ["/api/", /^https?:\/\/[^/]+\/api\//]
37	  });
38	}
39	
40	const rootEl = document.getElementById("root");
41	
42	if (!rootEl) {
43	  throw new Error("Root element #root not found in index.html");
44	}
45	
46	createRoot(rootEl).render(
47	  <StrictMode>
48	    <App />
49	  </StrictMode>
50	);
51	
52	logger.info({ event: "app.bootstrapped", mode: env.MODE });
53	
54	/*
55	 * Register the Web Push service worker. Best-effort: failure here doesn't
56	 * block the app — the SettingsPage reports "not supported" / "blocked" via
57	 * the useWebPush hook. Only attempt registration in browsers that support
58	 * service workers (Safari < 16 doesn't ship Push API + VAPID).
59	 */
60	if ("serviceWorker" in navigator) {
61	  void navigator.serviceWorker.register("/sw.js").catch((error: unknown) => {
62	    logger.warn({
63	      event: "service_worker.register_failed",
64	      error: getErrorMessage(error)
65	    });
66	  });
67	}
